// @generated by tilo-app; screen graph registry.
// Edit screen graphs under ui/; tilo-app maintains this registry.
// tilo-app:screen=about
// tilo-app:screen=main

use ui::widget::Widget;
use ui::{RouteError, RouteHandle, Router, Theme, UiBuildContext, UiGraphError, UiGraphHandle};

pub const NAMES: &[&str] = &["about", "main"];

/// Build the `about` screen.
///
/// # Errors
///
/// Returns a graph parse, validation, component, or construction error.
pub fn about(theme: &Theme) -> Result<Box<dyn Widget>, UiGraphError> {
    about_with(theme, UiBuildContext::default())
}

/// Build `about` with app-owned component factories and other services.
///
/// # Errors
///
/// Returns a graph parse, validation, component, or construction error.
pub fn about_with(theme: &Theme, context: UiBuildContext) -> Result<Box<dyn Widget>, UiGraphError> {
    build_with("about", include_str!("../ui/about.json"), theme, context)
}

/// Build the `main` screen.
///
/// # Errors
///
/// Returns a graph parse, validation, component, or construction error.
pub fn main(theme: &Theme) -> Result<Box<dyn Widget>, UiGraphError> {
    main_with(theme, UiBuildContext::default())
}

/// Build `main` with app-owned component factories and other services.
///
/// # Errors
///
/// Returns a graph parse, validation, component, or construction error.
pub fn main_with(theme: &Theme, context: UiBuildContext) -> Result<Box<dyn Widget>, UiGraphError> {
    build_with("main", include_str!("../ui/main.json"), theme, context)
}

/// Build a screen selected at run time.
pub fn get(name: &str, theme: &Theme) -> Option<Result<Box<dyn Widget>, UiGraphError>> {
    match name {
        "about" => Some(about(theme)),
        "main" => Some(main(theme)),
        _ => None,
    }
}

fn get_routed(
    name: &str,
    theme: &Theme,
    navigation: &RouteHandle,
    context: &UiBuildContext,
) -> Option<Result<Box<dyn Widget>, UiGraphError>> {
    let source = match name {
        "about" => include_str!("../ui/about.json"),
        "main" => include_str!("../ui/main.json"),
        _ => return None,
    };
    let context = context.clone().with_router(navigation.clone());
    Some(build_with(name, source, theme, context))
}

/// Build a history-aware host for all registered screens.
///
/// # Errors
///
/// Returns an error when the initial route or a screen is invalid.
pub fn router(initial: &str, theme: &Theme) -> Result<Router, RouteError> {
    router_with(initial, theme, UiBuildContext::default())
}

/// Build the screen router with app-owned component factories and services.
///
/// # Errors
///
/// Returns an error when the initial route or a screen is invalid.
pub fn router_with(
    initial: &str,
    theme: &Theme,
    context: UiBuildContext,
) -> Result<Router, RouteError> {
    Router::new(
        initial,
        NAMES.iter().copied(),
        theme,
        move |route, theme, navigation| {
            get_routed(route, theme, navigation, &context)
                .ok_or_else(|| format!("screen {route:?} is not registered"))?
                .map_err(|error| error.to_string())
        },
    )
}

fn build_with(
    screen: &str,
    source: &str,
    theme: &Theme,
    context: UiBuildContext,
) -> Result<Box<dyn Widget>, UiGraphError> {
    let graph = UiGraphHandle::from_embedded_or_live(screen, source)?;
    Ok(Box::new(graph.widget_with(theme, context)?))
}
